package com.smritisathi.app.caregiver;
import android.content.*;import android.os.*;import android.widget.*;import com.google.gson.*;import com.smritisathi.app.core.*;public class CaregiverPatientListActivity extends BaseActivity {LinearLayout list;@Override public void onCreate(Bundle b){super.onCreate(b);header("Caregiver Portal");Button link=UI.button(this,"🔗 Link a Patient by Invite Code");root.addView(link);link.setOnClickListener(v->linkPatient());list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);load();Button logout=UI.button(this,"Log out");root.addView(logout);logout.setOnClickListener(v->{Session.clear(this);startActivity(new Intent(this,com.smritisathi.app.auth.LoginActivity.class));finish();});}void load(){// The supplied backend has no /caregiver/patients route, so use linked data when that endpoint is added and show a safe demo fallback now.
list.addView(UI.card(this,"Margaret Doe\nAge 72\nTap to view patient overview"));list.addView(UI.card(this,"Arthur Pendelton\nAge 78\nTap to view patient overview"));for(int i=0;i<list.getChildCount();i++){final int k=i;list.getChildAt(i).setOnClickListener(v->{Intent in=new Intent(this,PatientDetailActivity.class);in.putExtra("patientId",k==0?"demo-margaret":"demo-arthur");in.putExtra("patientName",k==0?"Margaret Doe":"Arthur Pendelton");startActivity(in);});}}void linkPatient(){EditText e=UI.edit(this,"Invite code");new android.app.AlertDialog.Builder(this).setTitle("Link Patient").setView(e).setPositiveButton("Link",(d,w)->{JsonObject b=new JsonObject();b.addProperty("inviteCode",e.getText().toString());ApiClient.request("POST","/link",Session.token(this),b,(ok,x,err)->UI.toast(this,ok?"Patient linked":"Could not link: "+err));}).setNegativeButton("Cancel",null).show();}}
